  function renderIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{const name=el.dataset.icon;if(!iconPaths[name]||el.querySelector('svg'))return;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('aria-hidden','true');svg.innerHTML=iconPaths[name];el.appendChild(svg)})}
  const app=document.getElementById('app');const params=new URLSearchParams(location.search);const view=params.get('view')||'timeline';const collapsed=params.get('collapsed')==='1'||view==='collapsed';
  function setView(name,push=false){app.classList.remove('view-timeline','view-podcast','view-search','view-starred','view-notes');app.classList.add(`view-${name}`);document.getElementById('settings-modal').classList.remove('is-open');const title=document.getElementById('master-title');const map={timeline:'时间线 <span class="title-count">12</span>',podcast:'音频 <span class="title-count">3</span>',search:'搜索 <span class="title-count">3</span>',starred:'收藏 <span class="title-count">6</span>',notes:'笔记 <span class="title-count">8</span>'};title.innerHTML=map[name]||map.timeline;if(name==='podcast')app.querySelector('.window-label').textContent='播放队列';else if(name==='search')app.querySelector('.window-label').textContent='本地搜索';else app.querySelector('.window-label').textContent='最近 30 天';if(push){const p=new URLSearchParams(location.search);p.set('view',name);history.replaceState({},'',`${location.pathname}?${p}`)}}
