  app.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='collapse-sidebar'){app.classList.toggle('sidebar-collapsed');return}if(action==='view-timeline'){setView('timeline',true);app.classList.remove('show-detail');return}if(action==='view-search'){setView('search',true);app.classList.remove('show-detail');return}if(action==='view-starred'){setView('starred',true);app.classList.remove('show-detail');return}if(action==='view-podcast'){setView('podcast',true);app.classList.remove('show-detail');return}if(action==='view-notes'){setView('notes',true);app.classList.remove('show-detail');return}if(action==='view-settings'){document.getElementById('settings-modal').classList.add('is-open');return}if(action==='close-settings'){document.getElementById('settings-modal').classList.remove('is-open');return}if(action==='mobile-back'){app.classList.remove('show-detail');return}const row=e.target.closest('.story-row,.queue-row,.search-result');if(row){row.parentElement.querySelectorAll('.is-selected').forEach(x=>x.classList.remove('is-selected'));row.classList.add('is-selected');if(matchMedia('(max-width:899px)').matches)app.classList.add('show-detail')}});
